    35→		return;
    36→	}
    37→
    38→	manager = new WebSocketManager(options);
    39→
    40→	// AC: @web-dashboard ac-29 - Track connection state
    41→	manager.onStateChange((state) => {
    42→		connectionState = state;
    43→		connectionLost = manager!.isConnectionLost();
    44→	});
    45→
    46→	manager.connect();
    47→}
    48→
    49→/**
    50→ * Reconnect with a different project
    51→ * AC: @multi-directory-daemon ac-27
    52→ */
    53→export function reconnectWithProject(projectPath: string | null): void {
    54→	if (!manager) {
    55→		console.warn('[ConnectionStore] Not initialized, cannot reconnect with project');
    56→		return;
    57→	}
    58→
    59→	manager.setProjectPath(projectPath);
    60→}
    61→
    62→/**
    63→ * Get connection state
    64→ * AC: @web-dashboard ac-29
    65→ */
    66→export function getConnectionState(): ConnectionState {
    67→	return connectionState;
    68→}
    69→
    70→/**
    71→ * Check if connection is lost (>10s)
    72→ * AC: @web-dashboard ac-29
    73→ */
    74→export function isConnectionLost(): boolean {
    75→	return connectionLost;
    76→}
    77→
    78→/**
    79→ * Check if connected
    80→ */
    81→export function isConnected(): boolean {
    82→	return manager?.isConnected() ?? false;
    83→}
    84→
    85→/**
    86→ * Subscribe to topics
    87→ * AC: @web-dashboard ac-32
    88→ */
    89→export function subscribe(topics: string[]): void {
    90→	if (!manager) {
    91→		// No-op during SSR or before initialization
    92→		return;
    93→	}
    94→	manager.subscribe(topics);
    95→}
    96→
    97→/**
    98→ * Unsubscribe from topics
    99→ */
   100→export function unsubscribe(topics: string[]): void {
   101→	if (!manager) {
   102→		// No-op during SSR or before initialization
   103→		return;
   104→	}
   105→	manager.unsubscribe(topics);
   106→}
   107→
   108→/**
   109→ * Register event handler
   110→ * AC: @web-dashboard ac-33
   111→ */
   112→export function on(topic: string, handler: (event: any) => void): void {
   113→	if (!manager) {
   114→		// No-op during SSR or before initialization
   115→		return;
   116→	}
   117→	manager.on(topic, handler);
   118→}
   119→
   120→/**
   121→ * Unregister event handler
   122→ */
   123→export function off(topic: string, handler: (event: any) => void): void {
   124→	if (!manager) {
   125→		// No-op during SSR or before initialization
   126→		return;
   127→	}
   128→	manager.off(topic, handler);
   129→}
   130→
   131→/**
   132→ * Disconnect
   133→ */
   134→export function disconnect(): void {
   135→	if (manager) {
   136→		manager.disconnect();
   137→		manager = null;
   138→	}
   139→}
   140→
   141→/**
   142→ * Get connection statistics
   143→ */
   144→export function getConnectionStats() {
   145→	return manager?.getStats();
   146→}
   147→
   148→/**
   149→ * Get active subscriptions
   150→ */
   151→export function getSubscriptions(): string[] {
