export async function fetchAlignment(): Promise<AlignmentResponse> {
	if (isStaticMode()) {
		return {
			stats: { totalSpecs: 0, specsWithTasks: 0, alignedSpecs: 0, orphanedSpecs: 0 },
			warnings: []
		};
