/**
 * WebSocketManager
 *
 * Manages WebSocket connection lifecycle with exponential backoff reconnection,
 * sequence deduplication, and automatic topic re-subscription.
 *
 * AC Coverage:
 * - ac-28 (@web-dashboard): Exponential backoff reconnect (1s, 2s, 4s... max 30s)
 * - ac-29 (@web-dashboard): Connection lost indicator after 10s
 * - ac-30 (@web-dashboard): Sequence deduplication (skip seq <= lastSeqProcessed)
 * - ac-31 (@web-dashboard): Reset lastSeqProcessed = -1 on reconnect
 * - ac-32 (@web-dashboard): Re-subscribe to all topics on reconnect
 * - ac-33 (@web-dashboard): Trigger update handlers on broadcast events
 * - ac-34 (@multi-directory-daemon): Project path as query parameter for WebSocket
 */

import type {
	WebSocketCommand,
	WebSocketMessage,
	BroadcastEvent,
	ConnectedEvent,
	CommandAck
} from '@kynetic-ai/shared';
import type {
	ConnectionState,
	Subscription,
	ConnectionStats,
	EventHandler,
	StateChangeHandler
} from './types.js';
import { DAEMON_WS_BASE } from '../constants.js';

const DEFAULT_URL = `${DAEMON_WS_BASE}/ws`;
const MAX_BACKOFF_MS = 30000; // 30s
const CONNECTION_LOST_THRESHOLD_MS = 10000; // 10s
const MAX_RECONNECT_ATTEMPTS = 10;

export interface WebSocketManagerOptions {
	url?: string;
	projectPath?: string;
}

export class WebSocketManager {
	private ws: WebSocket | null = null;
	private baseUrl: string;
	private projectPath: string | null;
	private state: ConnectionState = 'disconnected';
	private intentionalDisconnect = false;
	private subscriptions = new Map<string, Subscription>();
	private eventHandlers = new Map<string, Set<EventHandler>>();
	private stateChangeHandlers = new Set<StateChangeHandler>();

	// AC: @web-dashboard ac-30, ac-31
	private lastSeqProcessed = -1;

	// AC: @web-dashboard ac-28
	private reconnectAttempts = 0;
	private reconnectTimer: ReturnType<typeof setTimeout> | null = null;

	// AC: @web-dashboard ac-29
	private connectionLostTimer: ReturnType<typeof setTimeout> | null = null;

	private stats: ConnectionStats = {
		connect_count: 0,
		reconnect_count: 0,
		last_connected_at: null,
		last_disconnected_at: null
	};

	constructor(options: WebSocketManagerOptions | string = {}) {
		// Support both old string signature and new options object
		if (typeof options === 'string') {
			this.baseUrl = options;
			this.projectPath = null;
		} else {
			this.baseUrl = options.url || DEFAULT_URL;
			this.projectPath = options.projectPath || null;
		}
	}

	/**
	 * Get the full WebSocket URL with project path as query param if set
	 * AC: @multi-directory-daemon ac-34
	 */
	private getUrl(): string {
		if (!this.projectPath) {
			return this.baseUrl;
		}
		const url = new URL(this.baseUrl);
		url.searchParams.set('project', this.projectPath);
		return url.toString();
	}

	/**
	 * Update the project path and trigger reconnection if connected
	 * AC: @multi-directory-daemon ac-27
	 */
	setProjectPath(path: string | null): void {
		if (this.projectPath === path) return;

		this.projectPath = path;

		// If connected, disconnect and reconnect with new project
		if (this.isConnected()) {
			this.reconnectAttempts = 0; // Reset so we try fresh
			this.disconnect();
			this.connect();
		}
	}

	/**
	 * Get current project path
	 */
	getProjectPath(): string | null {
		return this.projectPath;
	}

	/**
	 * Get current connection state
	 * AC: @web-dashboard ac-29
	 */
	getState(): ConnectionState {
		return this.state;
	}

	/**
	 * Check if connection is established
	 * AC: @web-dashboard ac-29
	 */
	isConnected(): boolean {
		return this.state === 'connected';
	}

	/**
	 * Check if connection has been lost for > threshold
	 * AC: @web-dashboard ac-29
	 */
	isConnectionLost(): boolean {
		if (this.state === 'connected') return false;
		if (!this.stats.last_disconnected_at) return false;

		const timeSinceDisconnect = Date.now() - this.stats.last_disconnected_at.getTime();
		return timeSinceDisconnect > CONNECTION_LOST_THRESHOLD_MS;
	}

	/**
	 * Connect to WebSocket server
	 * AC: @web-dashboard ac-28
	 * AC: @multi-directory-daemon ac-34 - Includes project as query param
	 */

