     7→ * daemon, so we use same-origin requests. In dev mode (Vite on port 5173),
     8→ * the daemon runs on a separate port so we fall back to the default.
     9→ */
    10→
    11→export const DAEMON_PORT = 3456;
    12→
    13→function getDaemonApiBase(): string {
    14→	if (typeof window === 'undefined') return `http://localhost:${DAEMON_PORT}`;
    15→	// In dev mode, Vite serves on a different port than the daemon
    16→	const isDev = import.meta.env?.DEV;
    17→	if (isDev) return `http://localhost:${DAEMON_PORT}`;
    18→	// Production: daemon serves the web UI, so use same-origin
    19→	return window.location.origin;
    20→}
    21→
    22→function getDaemonWsBase(): string {
    23→	if (typeof window === 'undefined') return `ws://localhost:${DAEMON_PORT}`;
    24→	const isDev = import.meta.env?.DEV;
    25→	if (isDev) return `ws://localhost:${DAEMON_PORT}`;
    26→	const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    27→	return `${protocol}//${window.location.host}`;
    28→}
    29→
    30→export const DAEMON_API_BASE = getDaemonApiBase();
    31→export const DAEMON_WS_BASE = getDaemonWsBase();
    32→
